$ErrorActionPreference='Stop'
$book=@{}; $s=''
foreach($line in Get-Content workbook_inspection.txt){if($line.StartsWith('SHEET: ')){$s=$line.Substring(7);$book[$s]=@{};continue};foreach($part in ($line -split ' \| ')){if($part -match '^([A-Z]+)(\d+)=(.*)$'){$book[$s][$matches[1]+$matches[2]]=$matches[3]}}}
function V($s,$c,$r){return $book[$s]["$c$r"]}
function Num($v){$n=0.0;if([double]::TryParse("$v",[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$n)){return $n};return $null}
function Date($v){if(Num $v){return [datetime]::FromOADate([double]$v).ToString('yyyy-MM-dd')};return ''}
$cols='record_id,record_type,experiment_id,date,date_basis,crop,variety,variety_raw,wall_id,side,tube_id,slot_id,tray_id,plant_count,harvest_weight,harvest_weight_status,fruit_count,leaves_slot_2,leaves_slot_4,leaves_slot_6,mean_sampled_leaves,weight_per_plant,seed_date,transplant_date,days_since_sowing,days_since_transplant,light_zone,light_bar,light_value,light_zone_mean,light_distance,light_join_basis,position,trial,water_volume_ml,water_duration_min,water_pressure_psi,water_tube_trial_mean_ml,tank,do_static,do_running,dap_reported,notes,source_sheet,source_cells,context_sources' -split ','
$rows=[Collections.Generic.List[object]]::new()
function Row($type,$sheet,$cells){$d=[ordered]@{};foreach($c in $cols){$d[$c]=$null};$d.record_id='r{0:d5}' -f ($rows.Count+1);$d.record_type=$type;$d.experiment_id='RES406_spring2026';$d.source_sheet=$sheet;$d.source_cells=$cells;return $d}
function Variety($v){switch -Regex ($v.Trim().ToLower()){'^bloom' {'Bloomsdale';break};'^top' {'Top Bunch';break};'^trop' {'Tropicana';break};'^butter' {'Green Butter';break};'^argula$|^arugula$' {'Arugula';break};default {if($v){(Get-Culture).TextInfo.ToTitleCase($v.Trim().ToLower())}}}}
# Correct a missing side letter using the surrounding 2B block.
$book['Grow Wall Lighting']['C31']=$book['Grow Wall Lighting']['C31'].Replace('Lightwall 2_2','Lightwall 2b_2')
$zones=@()
foreach($hr in @(1,11,21,31,41,51)){foreach($c in @('B','C','D','E','F','G')){$label=V 'Grow Wall Lighting' $c $hr;if($label -match 'Lightwall (\d)([ab])_(\d).*?\((?:Tube\s*)?(\d+)\s*-\s*(\d+)\)'){$wall=[int]$matches[1];$side=$matches[2].ToUpper();$id=$matches[3];$lo=[int]$matches[4];$hi=[int]$matches[5];$vals=@();foreach($bar in 1..7){$n=Num (V 'Grow Wall Lighting' $c ($hr+$bar));$vals+=$n;$d=Row 'wall_lighting' 'Grow Wall Lighting' "$c$($hr+$bar)";$d.wall_id=$wall;$d.side=$side;$d.light_zone=$id;$d.light_bar=$bar;$d.light_value=$n;$d.light_distance=Num (V 'Grow Wall Lighting' $c ($hr+8));$d.notes=$label;$rows.Add([pscustomobject]$d)};$zones+= [pscustomobject]@{wall=$wall;side=$side;id=$id;lo=$lo;hi=$hi;mean=($vals|Measure-Object -Average).Average;distance=(Num (V 'Grow Wall Lighting' $c ($hr+8)))}}}}
$water=@{}
foreach($b in @(@(1,3,8),@(2,12,17),@(3,21,26))){foreach($r in $b[1]..$b[2]){$tube=V 'Grow Wall_Water_Output' 'A' $r;$vals=@();foreach($ix in 0..3){$c=@('B','C','D','E')[$ix];$n=Num (V 'Grow Wall_Water_Output' $c $r);if($null -ne $n){$vals+=$n;$d=Row 'water_output' 'Grow Wall_Water_Output' "$c$r";$d.wall_id=$b[0];$d.tube_id=$tube;$d.trial=$ix+1;$d.water_volume_ml=$n;$d.water_duration_min=5;$d.water_pressure_psi=25;$rows.Add([pscustomobject]$d)}};$water["$($b[0])/$tube"]=($vals|Measure-Object -Average).Average}}
$specs=@(@('Spinach_Data','Spinach','B','J'),@('Collards_Data','Collards','A','I'),@('Lettuce_Data','Lettuce','A','I'),@('Kale_Arugula Data','Mixed','B','J'))
$letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ'
foreach($spec in $specs){$sheet=$spec[0];foreach($hr in @(2,20)){foreach($start in @($spec[2],$spec[3])){$label=V $sheet $start $hr;if($label -notmatch 'Grow Wall (\d)([AB])'){throw "Missing block $sheet $start$hr"};$wall=[int]$matches[1];$side=$matches[2];$ci=$letters.IndexOf($start);foreach($r in ($hr+2)..($hr+15)){$tube=Num (V $sheet $start $r);if($null -eq $tube){continue};$raw=V $sheet ([string]$letters[$ci+5]) $r;if(!$raw){continue};$var=Variety $raw;$crop=$spec[1];if($crop -eq 'Mixed'){$crop=$var};$d=Row 'harvest' $sheet "$start${r}:$($letters[$ci+6])$r";$d.crop=$crop;$d.variety=$var;$d.variety_raw=$raw;$d.wall_id=$wall;$d.side=$side;$d.tube_id=$tube;$w=V $sheet ([string]$letters[$ci+1]) $r;$d.harvest_weight=Num $w;$d.harvest_weight_status=if($null -eq $d.harvest_weight){$w.Trim()}else{'observed'};$d.plant_count=Num (V $sheet ([string]$letters[$ci+6]) $r);foreach($i in 2..4){$d[@('leaves_slot_2','leaves_slot_4','leaves_slot_6')[$i-2]]=Num (V $sheet ([string]$letters[$ci+$i]) $r)};$rows.Add([pscustomobject]$d)}}}}
foreach($sp in @(@('Cucumber_Data','Cucumber'),@('Bell Pepper_Data','Bell Pepper'))){foreach($side in @('A','B')){$cs=if($side -eq 'A'){@('A','B','C','D')}else{@('G','H','I','J')};foreach($r in 2..29){$raw=V $sp[0] $cs[0] $r;$tube=Num (V $sp[0] $cs[1] $r);if(!$raw -or $null -eq $tube){continue};$d=Row 'harvest' $sp[0] "$($cs[0])${r}:$($cs[3])$r";$d.crop=$sp[1];$d.variety_raw=$raw;$d.variety=Variety $raw;$d.wall_id=1;$d.side=$side;$d.tube_id=$tube;$d.fruit_count=Num (V $sp[0] $cs[2] $r);$d.harvest_weight=Num (V $sp[0] $cs[3] $r);$d.harvest_weight_status=if($null -eq $d.harvest_weight){'not_recorded'}else{'observed'};$rows.Add([pscustomobject]$d)}}}
$logmap=@{Myers='Lab';Collards='Collards';Spinach='Spinach';Lettuce='Lettuce';Peppers='Bell Pepper';Cucs='Cucumber';Kale_Arugula='Kale;Arugula'}
foreach($sheet in $logmap.Keys){foreach($r in 2..116){$notes=@();foreach($c in @('B','C','E','G')){$v=V $sheet $c $r;if($v -and $null -eq (Num $v)){$notes+=$v.Trim()}};if(!$notes.Count){continue};$d=Row 'lab_event' $sheet "A${r}:G$r";$d.date=Date (V $sheet 'A' $r);$d.date_basis='explicit_log_date';$d.crop=$logmap[$sheet];$d.notes=$notes -join ' | ';$d.dap_reported=Num (V $sheet 'B' $r);$rows.Add([pscustomobject]$d)}}
foreach($r in 2..27){$tray=V 'SeedlingTable_Lighting' 'A' $r;if(!$tray){continue};foreach($i in 0..2){$c=@('C','D','E')[$i];$d=Row 'seedling_lighting' 'SeedlingTable_Lighting' "$c$r";$d.tray_id=$tray;$d.variety_raw=V 'SeedlingTable_Lighting' 'B' $r;$d.variety=Variety $d.variety_raw;$d.position=@('front','middle','back')[$i];$d.light_value=Num (V 'SeedlingTable_Lighting' $c $r);$rows.Add([pscustomobject]$d)}}
foreach($r in 2..4){$d=Row 'dissolved_oxygen' 'DO' "A${r}:D$r";$d.date=Date (V 'DO' 'A' $r);$d.date_basis='explicit_measurement_date';$d.tank=V 'DO' 'D' $r;$d.do_static=Num (V 'DO' 'B' $r);$d.do_running=Num (V 'DO' 'C' $r);$rows.Add([pscustomobject]$d)}
# Preserve layout observations at their actual slot grain.
foreach($sheet in @('GW1_Layout','GW2 & 3 Layout ')){$wall=$null;$side=$null;$header=0;foreach($r in 1..65){$label=V $sheet 'A' $r;if($label -match 'Wall\s*(\d)[ _]*([AB])'){$wall=[int]$matches[1];$side=$matches[2];$header=if($sheet -eq 'GW1_Layout'){$r}else{$r+1}};if($label -match '^Slot\s*(\d+)$'){$slot=$matches[1];foreach($k in $book[$sheet].Keys){if($k -match '^([A-Z]+)(\d+)$' -and [int]$matches[2] -eq $r -and $matches[1] -ne 'A'){$c=$matches[1];$tube=Num (V $sheet $c $header);if($null -eq $tube){continue};$raw=V $sheet $c $r;$d=Row 'layout' $sheet $k;$d.wall_id=$wall;$d.side=$side;$d.tube_id=$tube;$d.slot_id=$slot;$d.variety_raw=$raw;$d.variety=Variety $raw;$rows.Add([pscustomobject]$d)}}}}}
$events=@($rows | Where-Object record_type -eq 'lab_event')
foreach($d in $rows | Where-Object record_type -eq 'harvest'){
$z=@($zones | Where-Object {$_.wall -eq $d.wall_id -and $_.side -eq $d.side -and $d.tube_id -ge $_.lo -and $d.tube_id -le $_.hi});if($z.Count -eq 1){$d.light_zone=$z[0].id;$d.light_zone_mean=$z[0].mean;$d.light_distance=$z[0].distance;$d.light_join_basis='tube_in_labeled_range_undated'}else{$d.light_join_basis='boundary_tube_unassigned'}
$d.water_tube_trial_mean_ml=$water["$($d.wall_id)/$($d.tube_id)"]
$l=@($events | Where-Object {$_.record_type -eq 'lab_event' -and ($_.crop -eq $d.crop -or ($_.crop -eq 'Kale;Arugula' -and $d.crop -in @('Kale','Arugula')))})
$seed=@($l | Where-Object {$_.notes -match 'planted|replanted' -and $_.notes -notmatch 'Transplanted|into wall'} | Sort-Object date);if($seed.Count){$d.seed_date=$seed[-1].date}
$trans=@($l | Where-Object {$_.notes -match 'Transplanted|into wall'});if($trans.Count){$d.transplant_date=$trans[0].date}
$h=@($l | Where-Object {$_.notes -match 'Harvested' -and ($_.notes -notmatch 'grow.*[23]' -or $_.notes -match "(?:grow.*) $($d.wall_id)\)" )});if($h.Count -eq 1){$d.date=$h[0].date;$d.date_basis='inferred_crop_wall_harvest_log';if($d.seed_date){$d.days_since_sowing=([datetime]$d.date-[datetime]$d.seed_date).Days};if($d.transplant_date){$d.days_since_transplant=([datetime]$d.date-[datetime]$d.transplant_date).Days}}
$leaves=@($d.leaves_slot_2,$d.leaves_slot_4,$d.leaves_slot_6 | Where-Object {$null -ne $_});if($leaves.Count){$d.mean_sampled_leaves=($leaves | Measure-Object -Average).Average};if($d.plant_count -gt 0 -and $null -ne $d.harvest_weight){$d.weight_per_plant=$d.harvest_weight/$d.plant_count};$d.context_sources='Grow Wall Lighting;crop log';if($null -ne $d.water_tube_trial_mean_ml){$d.context_sources+=';Grow Wall_Water_Output'}
}
$rows | Export-Csv hydroponics_ml.csv -NoTypeInformation -Encoding UTF8
$rows | Group-Object record_type | Select-Object Name,Count | Format-Table
$harvest=@($rows | Where-Object record_type -eq 'harvest');if(($harvest | Group-Object {"$($_.crop)/$($_.wall_id)/$($_.side)/$($_.tube_id)"} | Where-Object Count -gt 1)){throw 'Duplicate harvest keys'}
'Harvests with inferred dates: '+@($harvest|Where-Object date).Count
'Harvests with light joins: '+@($harvest|Where-Object light_zone_mean).Count
'CSV rows: '+@(Import-Csv hydroponics_ml.csv).Count

